#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODES 200005
#define ALPHABET_SIZE 36

typedef struct {
    int next[ALPHABET_SIZE];
    int count;
} TrieNode;

TrieNode trie[MAX_NODES];
int trie_nodes = 1;

int get_char_index(char c) {
    if (c >= 'a' && c <= 'z') {
        return c - 'a';
    }
    return c - '0' + 26;
}

void insert_trie(const char *s) {
    int u = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        int c = get_char_index(s[i]);
        if (trie[u].next[c] == 0) {
            trie[u].next[c] = trie_nodes++;
        }
        u = trie[u].next[c];
    }
    trie[u].count++;
}

int query_trie(const char *s) {
    int u = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        int c = get_char_index(s[i]);
        if (trie[u].next[c] == 0) {
            return 0;
        }
        u = trie[u].next[c];
    }
    return trie[u].count;
}

char passwords[20005][12];

int cmp_str(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", passwords[i]);
        insert_trie(passwords[i]);
    }

    long long total_pairs = 0;
    char subs[60][12];

    for (int i = 0; i < n; i++) {
        int len = strlen(passwords[i]);
        int num_subs = 0;

        for (int j = 0; j < len; j++) {
            for (int k = j; k < len; k++) {
                int sub_len = k - j + 1;
                memcpy(subs[num_subs], passwords[i] + j, sub_len);
                subs[num_subs][sub_len] = '\0';
                num_subs++;
            }
        }

        qsort(subs, num_subs, sizeof(subs[0]), cmp_str);

        for (int j = 0; j < num_subs; j++) {
            if (j == 0 || strcmp(subs[j], subs[j - 1]) != 0) {
                total_pairs += query_trie(subs[j]);
            }
        }

        // Subtrai o próprio usuário B = A
        total_pairs--;
    }

    printf("%lld\n", total_pairs);

    return 0;
}
